+test("cook operations are audited once and audit lists newest first", async () => {
+  const { handle, store } = app();
+  const headers = { authorization: "Bearer seed-cook" };
+  let saves = 0;
+  store.save = () => { saves++; };
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  const requests = [
+    { path: "/recipes/1/cook", body: { portions: 4 } },
+    { path: "/batches/6/waste", body: { qty: 0.1 } },
+    { path: "/temperatures", body: { location: "fridge", celsius: 4 } },
+    { path: `/stocktakes/${take.id}/counts`, body: { batchId: 6, counted: 10 } },
+  ];
+  for (const request of requests) {
+    const res = await handle({ ...request, method: "POST", headers });
+    assert.ok(res.status < 300, JSON.stringify(res));
+  }
