+  assert.equal(saves, 5);
+  const audit = (await handle({ path: "/audit" })).body;
+  assert.deepEqual(audit, store.data.audit.slice().reverse());
+  assert.deepEqual(audit[0], {
+    time: "2026-10-28T10:00:00.000Z", name: "Seed cook", method: "POST",
+    path: `/stocktakes/${take.id}/counts`, status: 200,
+  });
+  assert.equal(JSON.stringify(audit).includes("seed-cook"), false);
+});
